m as (select '{"m":{"abdominals":"Abdominaux","abductors":"Abducteurs","adductors":"Adducteurs","biceps":"Biceps","calves":"Mollets","chest":"Pectoraux","forearms":"Avant-bras","glutes":"Fessiers","hamstrings":"Ischio-jambiers","lats":"Grand dorsal","lower back":"Lombaires","middle back":"Milieu du dos","neck":"Cou","quadriceps":"Quadriceps","shoulders":"Épaules","traps":"Trapèzes","triceps":"Triceps"},"e":{"barbell":"Barre","dumbbell":"Haltères","machine":"Machine","cable":"Poulie","body only":"Poids du corps","kettlebells":"Kettlebell","bands":"Élastiques","e-z curl bar":"Barre EZ","exercise ball":"Swiss ball","medicine ball":"Medecine ball","foam roll":"Rouleau","other":"Autre"},"l":{"beginner":"Débutant","intermediate":"Intermédiaire","expert":"Avancé"},"c":{"strength":"Musculation","powerlifting":"Force athlétique","olympic weightlifting":"Haltérophilie","plyometrics":"Pliométrie","cardio":"Cardio","stretching":"Mobilité","strongman":"Strongman"}}'::jsonb j),
ess as (select x->>0 source, x->>1 nom, x->>2 consigne, o-1 i from jsonb_array_elements('[["Barbell_Bench_Press_-_Medium_Grip","Développé couché à la barre","Omoplates serrées, descends la barre au bas des pectoraux, pousse en expirant."],["Barbell_Incline_Bench_Press_-_Medium_Grip","Développé incliné à la barre","Banc à 30-45°, barre vers le haut des pectoraux, coudes à 45°."],["Dumbbell_Bench_Press","Développé couché haltères","Haltères au niveau de la poitrine, pousse en rapprochant légèrement les haltères."],["Incline_Dumbbell_Press","Développé incliné haltères","Banc incliné, descente contrôlée, poussée verticale."],["Close-Grip_Barbell_Bench_Press","Développé couché prise serrée","Mains largeur d''épaules, coudes près du corps pour cibler les triceps."],["Machine_Bench_Press","Développé couché à la machine","Poignées à hauteur de poitrine, pousse sans verrouiller les coudes."],["Smith_Machine_Incline_Bench_Press","Développé incliné à la Smith","Barre guidée vers le haut des pectoraux, trajectoire contrôlée."],["Dumbbell_Flyes","Écarté couché haltères","Bras légèrement fléchis, ouvre en arc jusqu''à l''étirement des pectoraux."],["Butterfly","Butterfly (pec deck)","Rapproche les bras devant toi en serrant les pectoraux, retour lent."],["Cable_Crossover","Écarté à la poulie vis-à-vis","Buste penché, ramène les poignées devant le bassin en arc."],["Pushups","Pompes","Corps gainé et aligné, poitrine près du sol, pousse jusqu''aux bras tendus."],["Dips_-_Chest_Version","Dips pectoraux","Buste penché en avant, descends jusqu''à l''étirement des pectoraux."],["Pullups","Tractions pronation","Prise large, tire la poitrine vers la barre, descente complète."],["Chin-Up","Tractions supination","Paumes vers toi, menton au-dessus de la barre, biceps engagés."],["Wide-Grip_Lat_Pulldown","Tirage vertical prise large","Tire la barre vers le haut de la poitrine, coudes vers le bas."],["Close-Grip_Front_Lat_Pulldown","Tirage vertical prise serrée","Prise serrée, tire vers le sternum en gardant le buste droit."],["Straight-Arm_Pulldown","Pull-over à la poulie bras tendus","Bras quasi tendus, ramène la barre vers les cuisses en contractant le dos."],["Bent_Over_Barbell_Row","Rowing barre buste penché","Dos plat, buste à 45°, tire la barre vers le nombril."],["One-Arm_Dumbbell_Row","Rowing haltère un bras","Main et genou sur le banc, tire l''haltère vers la hanche."],["Seated_Cable_Rows","Tirage horizontal assis","Dos droit, tire la poignée vers le ventre, omoplates serrées."],["T-Bar_Row_with_Handle","Rowing T-bar","Dos plat, tire la poignée vers la poitrine, coudes près du corps."],["Inverted_Row","Rowing inversé","Sous une barre, corps gainé, tire la poitrine vers la barre."],["Face_Pull","Face pull","Corde à hauteur du visage, tire vers le front en écartant les mains."],["Barbell_Deadlift","Soulevé de terre","Barre contre les tibias, dos plat, pousse le sol avec les jambes."],["Romanian_Deadlift","Soulevé de terre roumain","Jambes presque tendues, bascule le bassin vers l''arrière, barre près des cuisses."],["Sumo_Deadlift","Soulevé de terre sumo","Pieds larges, mains entre les jambes, buste plus droit."],["Good_Morning","Good morning","Barre sur les trapèzes, bascule le buste en poussant les hanches en arrière."],["Barbell_Shrug","Haussements d''épaules barre","Monte les épaules vers les oreilles, pause, descente lente."],["Dumbbell_Shrug","Haussements d''épaules haltères","Bras tendus, monte les épaules sans rouler."],["Superman","Superman","Allongé ventre au sol, décolle bras et jambes, tiens 2 secondes."],["Standing_Military_Press","Développé militaire debout","Gainage serré, pousse la barre au-dessus de la tête, tête qui avance."],["Seated_Dumbbell_Press","Développé épaules haltères assis","Dos calé, pousse les haltères au-dessus de la tête."],["Arnold_Dumbbell_Press","Développé Arnold","Paumes vers toi en bas, rotation pendant la poussée."],["Side_Lateral_Raise","Élévations latérales","Coudes légèrement fléchis, monte jusqu''à l''horizontale."],["Reverse_Flyes","Oiseau haltères","Buste penché, ouvre les bras sur les côtés, arrière d''épaules."],["Band_Pull_Apart","Écarté élastique","Bras tendus devant, écarte l''élastique jusqu''à la poitrine."],["Barbell_Curl","Curl barre","Coudes fixes le long du corps, monte sans balancer."],["Dumbbell_Bicep_Curl","Curl haltères","Supination en montant, descente contrôlée."],["Hammer_Curls","Curl marteau","Prise neutre, monte les haltères sans bouger les coudes."],["Preacher_Curl","Curl pupitre","Bras calés sur le pupitre, extension presque complète en bas."],["Cable_Hammer_Curls_-_Rope_Attachment","Curl marteau à la corde","Corde à la poulie basse, coudes fixes."],["Triceps_Pushdown","Extension triceps à la poulie","Coudes collés, pousse la barre jusqu''aux bras tendus."],["Triceps_Pushdown_-_Rope_Attachment","Extension triceps à la corde","Écarte la corde en bas du mouvement."],["Triceps_Overhead_Extension_with_Rope","Extension triceps nuque à la corde","Dos à la poulie, tends les bras au-dessus de la tête."],["Lying_Triceps_Press","Barre au front","Allongé, descends la barre vers le front, coudes fixes."],["Standing_Dumbbell_Triceps_Extension","Extension triceps haltère debout","Haltère derrière la tête à deux mains, tends les bras."],["Dips_-_Triceps_Version","Dips triceps","Buste droit, descends jusqu''à 90° aux coudes."],["Bench_Dips","Dips sur banc","Mains sur le banc derrière toi, descends en fléchissant les coudes."],["Tricep_Dumbbell_Kickback","Kickback haltère","Buste penché, bras collé, tends l''avant-bras vers l''arrière."],["Barbell_Full_Squat","Squat barre","Pieds largeur d''épaules, descends sous la parallèle, genoux dans l''axe des pieds."],["Front_Barbell_Squat","Squat avant","Barre sur l''avant des épaules, coudes hauts, buste droit."],["Goblet_Squat","Goblet squat","Haltère contre la poitrine, descends entre les genoux."],["Bodyweight_Squat","Squat poids du corps","Bras devant, hanches en arrière, talons au sol."],["Smith_Machine_Squat","Squat à la Smith","Pieds légèrement devant, descente contrôlée."],["Hack_Squat","Hack squat","Dos contre le dossier, descends jusqu''à 90° minimum."],["Leg_Press","Presse à cuisses","Pieds largeur de hanches, descends sans décoller le bassin."],["Dumbbell_Lunges","Fentes haltères","Grand pas en avant, genou arrière près du sol."],["Split_Squat_with_Dumbbells","Fentes bulgares haltères","Pied arrière surélevé, descends à la verticale."],["Dumbbell_Step_Ups","Montées sur banc haltères","Pousse avec la jambe du haut, sans t''aider de celle du bas."],["Leg_Extensions","Leg extension","Tends les jambes, pause en haut, descente lente."],["Lying_Leg_Curls","Leg curl allongé","Ramène les talons vers les fessiers, bassin plaqué."],["Seated_Leg_Curl","Leg curl assis","Fléchis les genoux, contrôle le retour."],["Barbell_Hip_Thrust","Hip thrust barre","Haut du dos sur le banc, pousse les hanches, serre les fessiers en haut."],["Barbell_Glute_Bridge","Pont fessier barre","Allongé au sol, barre sur les hanches, monte le bassin."],["Single_Leg_Glute_Bridge","Pont fessier une jambe","Une jambe tendue, monte le bassin avec l''autre."],["Glute_Kickback","Kickback fessier","À quatre pattes, pousse le talon vers le plafond."],["Standing_Calf_Raises","Mollets debout","Monte sur la pointe des pieds, pause, descends en étirement."],["Seated_Calf_Raise","Mollets assis","Genoux à 90°, monte les talons au maximum."],["Plank","Gainage planche","Sur les avant-bras, corps aligné, abdos et fessiers serrés."],["Side_Bridge","Gainage latéral","Sur un avant-bras, bassin haut, corps aligné."],["Crunches","Crunch","Enroule le haut du dos vers le bassin, sans tirer sur la nuque."],["Hanging_Leg_Raise","Relevés de jambes suspendu","Suspendu à la barre, monte les jambes sans balancer."],["Russian_Twist","Rotation russe","Assis, buste incliné, tourne d''un côté à l''autre."],["Ab_Roller","Roue abdominale","À genoux, déroule vers l''avant en gardant le dos neutre."],["Rope_Crunch","Crunch à la corde","À genoux face à la poulie, enroule le buste vers le sol."],["Mountain_Climbers","Mountain climbers","En position de pompe, ramène les genoux vers la poitrine en alternance."],["One-Arm_Kettlebell_Swings","Swing kettlebell un bras","Impulsion des hanches, la kettlebell monte à hauteur d''épaule."],["Front_Box_Jump","Saut sur box","Élan des bras, saute sur la box, réception souple."],["Rope_Jumping","Corde à sauter","Petits sauts sur l''avant des pieds, poignets qui tournent."],["Battling_Ropes","Battle ropes","Genoux fléchis, vagues alternées rapides avec les bras."],["Rowing_Stationary","Rameur","Pousse avec les jambes, puis tire avec les bras, retour inverse."],["Elliptical_Trainer","Vélo elliptique","Rythme régulier, dos droit, poignées actives."],["Air_Bike","Vélo crunch au sol","Coude vers le genou opposé en pédalant."]]'::jsonb) with ordinality t(x,o)),
