reste as (select e->>'id' source, row_number() over (order by o) rn from src
  where e->>'category' in ('strength','powerlifting','olympic weightlifting','plyometrics','cardio') and jsonb_array_length(e->'images')=2 and e->>'id' not in (select source from ess)),
tout as (select source, nom, consigne, i from ess union all select r.source, n.nom, null, 82+r.rn from reste r join noms n using (rn))
insert into public.exercices(id,nom,consigne,consigne_en,muscles,secondaires,materiel,niveau,categorie,force,mecanique,essentiel,sprite,source)
select 'x'||lpad(t.i::text,3,'0'), t.nom, t.consigne,
  case when t.consigne is null then (select string_agg(v,' ') from jsonb_array_elements_text(src.e->'instructions') v) end,
  array(select coalesce(m.j->'m'->>v,v) from jsonb_array_elements_text(src.e->'primaryMuscles') v),
  array(select coalesce(m.j->'m'->>v,v) from jsonb_array_elements_text(src.e->'secondaryMuscles') v),
  coalesce(m.j->'e'->>(src.e->>'equipment'),'Poids du corps'), m.j->'l'->>(src.e->>'level'), coalesce(m.j->'c'->>(src.e->>'category'),'Musculation'),
  src.e->>'force', src.e->>'mechanic', t.consigne is not null,
  array[t.i/20, t.i%20, case when t.i/20 = 36 then 10 else 20 end], t.source
from tout t join src on src.e->>'id'=t.source cross join m;